// Tagesreport-Nachricht für Salonbesitzer
const salon = $('DB: Aktive Salons').item.json;
const kpi = $('DB: KPIs berechnen').item.json;

const revenue = (kpi.revenue_cents / 100).toFixed(2).replace('.', ',');
const today = new Date().toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long' });

const noShowRate = kpi.booking_count > 0
  ? Math.round((kpi.no_show_count / kpi.booking_count) * 100)
  : 0;

const message = `📊 Tagesreport ${salon.salon_name}
${today}

💰 Umsatz: ${revenue} €
📅 Termine: ${kpi.booking_count} (${kpi.completed_count} abgeschlossen)
👤 Neukunden: ${kpi.new_clients}
❌ No-Shows: ${kpi.no_show_count} (${noShowRate}%)
📈 Auslastung: ${kpi.occupancy_pct}%
${kpi.avg_rating > 0 ? '⭐ Bewertung: ' + Number(kpi.avg_rating).toFixed(1) + '/5' : ''}

Guten Abend! 🌙`;

return [{
  json: {
    salon_id: salon.salon_id,
    owner_phone: salon.owner_phone,
    owner_name: salon.owner_name,
    message
  }
}];

